export const navItems = [
  { label: "Bookmarks", path: "/bookmarks", testId: "nav-bookmarks" },
];

import React, { useState } from "react";

interface Bookmark {
  id: string;
  url: string;
  title: string;
}

export function BookmarkPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [url, setUrl] = useState("");
  const [title, setTitle] = useState("");
  const [query, setQuery] = useState("");
  const [items] = useState<Bookmark[]>([]);

  return (
    <div>
      <form>
        <input
          data-testid="auth-email-input"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          data-testid="auth-password-input"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <button data-testid="auth-submit-btn" type="submit">
          Sign in
        </button>
      </form>
      <form data-testid="bookmark-form">
        <input
          data-testid="bookmark-url-input"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
        />
        <input
          data-testid="bookmark-title-input"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
      </form>
      <input
        data-testid="bookmark-search-input"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <ul data-testid="bookmark-list">
        {items.map((bm) => (
          <li key={bm.id}>{bm.title}</li>
        ))}
      </ul>
    </div>
  );
}
